export const getCreateInviteUrl = () => {
  return `/invites`;
};

export const createInvite = async (
  createInviteDto: CreateInviteDto,
  options?: Parameters<typeof httpClient>[1],
): Promise<CreateInviteResponseDto> => {
  const getHeaders = (
    h?: NonNullable<RequestInit["headers"]>,
  ): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(
          h as Iterable<Iterable<string>>,
          (entry) => Array.from(entry) as [string, string],
        ),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
  return httpClient<CreateInviteResponseDto>(getCreateInviteUrl(), {
    ...options,
    method: "POST",
    headers: { "Content-Type": "application/json", ...getHeaders(options?.headers) },
    body: JSON.stringify(createInviteDto),
  });
};

export const getCreateInviteMutationKey = () => ["createInvite"] as const;

export const getCreateInviteMutationOptions = <TError = ApiErrorDto, TContext = unknown>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof createInvite>>,
    TError,
    CreateInviteMutationVariables,
    TContext
  >;
  request?: SecondParameter<typeof httpClient>;
}): UseMutationOptions<
  Awaited<ReturnType<typeof createInvite>>,
  TError,
  CreateInviteMutationVariables,
  TContext
> => {
  const mutationKey = getCreateInviteMutationKey();
  const { mutation: mutationOptions, request: requestOptions } = options
    ? options.mutation && "mutationKey" in options.mutation && options.mutation.mutationKey
      ? options
      : { ...options, mutation: { ...options.mutation, mutationKey } }
    : { mutation: { mutationKey }, request: undefined };

  const mutationFn: MutationFunction<
    Awaited<ReturnType<typeof createInvite>>,
    CreateInviteMutationVariables
  > = (props) => {
    const { data } = props ?? {};

    return createInvite(data, requestOptions);
  };

  return { mutationFn, ...mutationOptions };
};

